// End-to-end test against the production build (run `pnpm build` first): `pnpm e2e`.
// Uses real files generated by Chromium (text PDFs with embedded fonts, a scanned PDF, a
// photographed-style receipt PNG), the production CSP from vercel.json, and fails on any
// console error or any request to a non-local origin.
import { execFileSync } from "node:child_process";
import { mkdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { chromium, firefox, webkit } from "playwright-core";
import { startServer } from "./serve.mjs";
import { findChromium } from "./chromium.mjs";

const PORT = 4321;
const BASE = `http://localhost:${PORT}`;
const TMP = join(tmpdir(), `papertrail-e2e-${Date.now()}`);
mkdirSync(TMP, { recursive: true });

const PHRASE = "heat pump compressor";
const NEW_TITLE = "E2E Heat Pump Warranty";
const TAG = "e2e-appliances";

const results = [];
let currentCheck = "";
async function check(name, fn) {
  currentCheck = name;
  const t = Date.now();
  try {
    await fn();
    results.push({ name, ok: true });
    console.log(`  ✓ ${name} (${Date.now() - t}ms)`);
  } catch (e) {
    results.push({ name, ok: false, error: e.message });
    console.log(`  ✗ ${name}: ${e.message.split("\n").slice(0, 4).join(" | ")}`);
  }
}
function assert(cond, msg) {
  if (!cond) throw new Error(msg);
}

const server = await startServer(PORT);
// BROWSER=chromium (default) | firefox | webkit. Fixtures are always generated with Chromium (page.pdf).
const ENGINE = process.env.BROWSER ?? "chromium";
const fixtureBrowser = await chromium.launch({ headless: true, executablePath: findChromium() });
const browser = ENGINE === "chromium" ? fixtureBrowser : await { firefox, webkit }[ENGINE].launch({ headless: true });
const problems = [];
const external = [];

const inflight = new Map();
function watch(context, label) {
  context.on("request", (r) => inflight.set(r, `${label} ${r.resourceType()} ${r.url()}`));
  context.on("requestfinished", (r) => inflight.delete(r));
  context.on("requestfailed", (r) => inflight.delete(r));
  context.on("request", (r) => {
    const u = new URL(r.url());
    if (!["localhost", "127.0.0.1"].includes(u.hostname) && !["data:", "blob:"].includes(u.protocol)) external.push(`${label}: ${r.url()}`);
  });
  context.on("response", (r) => r.status() >= 400 && problems.push(`[${label}] HTTP ${r.status()} ${r.url()}`));
  context.on("page", (p) => {
    // Ignored, precisely: errors raised inside Playwright's Firefox driver (chrome://juggler), and
    // WebKit's "Load failed" for a fetch aborted because the test navigated away mid-request.
    // Real load failures still fail the functional checks that depend on them.
    const benign = (text) => text.includes("chrome://juggler/") || text === "Load failed";
    p.on("console", (m) => m.type() === "error" && !benign(m.text()) && problems.push(`[${label} · ${currentCheck}] ${m.text()}`));
    p.on("pageerror", (e) => !benign(e.message) && problems.push(`[${label} · ${currentCheck}] pageerror: ${e.message} ${(e.stack ?? "").split("\n").slice(0, 3).join(" | ")}`));
  });
}

// ── Fixtures (generated by Chromium) ─────────────────────────────────────
const fx = await fixtureBrowser.newContext();
const fp = await fx.newPage();
const para = (n) => Array.from({ length: n }, () => "The homeowner agrees to keep the equipment accessible for inspection and to follow the maintenance schedule in this agreement.").join(" ");
