await check("survives a reload during processing of a large (120-page) PDF and finds text on page 117", async () => {
  await page.goto(BASE);
  await addFiles(page, [bigPdf]);
  await page.locator('[data-testid="queue-item"][data-phase="processing"]').waitFor({ timeout: 20000 });
  await page.reload();
  await page.locator('[data-testid="doc-row"]', { hasText: "Workshop" }).waitFor({ timeout: 15000 });
  await page.evaluate(() => {
    window.__maxGap = 0;
    let last = performance.now();
    window.__beat = setInterval(() => {
      const now = performance.now();
      window.__maxGap = Math.max(window.__maxGap, now - last);
      last = now;
    }, 16);
  });
  await idle(page, 180000);
  const stall = await page.evaluate(() => (clearInterval(window.__beat), window.__maxGap));
  console.log(`      (longest main-thread stall while processing the 120-page PDF: ${Math.round(stall)}ms)`);
  assert(stall < 500, `UI froze for ${Math.round(stall)}ms`);
  await page.waitForFunction(() => {
    const row = [...document.querySelectorAll('[data-testid="doc-row"]')].find((r) => r.textContent.includes("Workshop"));
    return row && !/Queued|Reading text/.test(row.textContent);
  }, null, { timeout: 120000 });
  const t0 = Date.now();
  await search(page, "rear axle torque");
  const r = page.locator('[data-testid="search-result"]', { hasText: "Workshop" });
  await r.waitFor({ timeout: 10000 });
  assert(await r.getByText("Page 117").count(), "page number 117 not shown");
  console.log(`      (search answered in ${Date.now() - t0}ms incl. typing)`);
});

