await check("changes in one tab appear in another open tab without reloading", async () => {
  const other = await ctxA.newPage();
  // Firefox's Playwright driver sometimes misses load events for a second tab even though the
  // page has loaded (verified: readyState "complete"), so wait for real content instead.
  if (ENGINE === "firefox") void other.evaluate((u) => (location.href = u), BASE).catch(() => undefined);
  else await other.goto(BASE);
  await other.locator('[data-testid="doc-row"]').first().waitFor({ timeout: 20000 });
  await page.goto(docUrl.replace(/&q=.*$/, ""));
  const tagBox = page.getByRole("combobox", { name: "Add a tag" });
  await tagBox.fill("cross-tab");
  await tagBox.press("Enter");
  await other.getByRole("navigation", { name: "Main" }).getByRole("button", { name: /cross-tab/ }).waitFor({ timeout: 10000 });
  await other.close();
});

await check("'/' on another page jumps to the library search", async () => {
  await page.goto(`${BASE}/dates/`);
  await page.getByRole("heading", { name: "Important dates" }).waitFor();
  await page.keyboard.press("/");
  await page.waitForURL(`${BASE}/`);
  await page.waitForFunction(() => document.activeElement?.id === "library-search", null, { timeout: 5000 });
});

// ── Context B: restore into a clean workspace, search, open, delete ──────
const ctxB = await browser.newContext({ viewport: { width: 1280, height: 860 } });
watch(ctxB, "B");
const pb = await ctxB.newPage();

