await check("restoring a backup from the sample workspace goes into the user's own library", async () => {
  await pb.getByRole("button", { name: /Explore with sample documents/ }).click();
  await pb.getByText("Sample workspace.").waitFor();
  await pb.waitForFunction(() => document.querySelectorAll('[data-testid="doc-row"]').length >= 8, null, { timeout: 30000 });
  await pb.goto(`${BASE}/settings/`);
  await pb.getByText("Restores into your own library").waitFor();
  await pb.getByTestId("restore-input").setInputFiles(backupPath);
  await pb.getByRole("heading", { name: "Restore this backup?" }).waitFor({ timeout: 20000 });
  assert(!(await pb.getByText("Sample workspace.").count()), "still in the sample workspace");
  await pb.getByTestId("confirm-restore").click();
  await pb.getByTestId("restore-result").filter({ hasText: "Restored 1 document" }).waitFor({ timeout: 20000 });
  const counts = await idbCounts(pb);
  assert(counts.documents === 1, `user library should have the restored document: ${JSON.stringify(counts)}`);
});

// ── Context C: a library of hundreds of documents stays responsive ───────
const ctxC = await browser.newContext({ viewport: { width: 1280, height: 860 } });
watch(ctxC, "C");
const pc = await ctxC.newPage();
const many = [];
const words = "invoice receipt warranty policy lease bill payment amount total due renewal coverage tenant meter energy order serial refund delivery".split(" ");
mkdirSync(join(TMP, "many"), { recursive: true });
for (let i = 0; i < 400; i++) {
  const body = Array.from({ length: 400 }, (_, k) => words[(i * 7 + k * 13) % words.length]).join(" ");
  const f = join(TMP, "many", `note-${String(i).padStart(3, "0")}.txt`);
  writeFileSync(f, `Note ${i}\nReference code ZX${i}Q\n${body}\n`);
  many.push(f);
}

await check("imports 400 documents without freezing the page; list is virtualized; search stays fast", async () => {
  await pc.goto(BASE);
  // Event-loop heartbeat: the longest gap between 16 ms timer ticks is how long the page was frozen.
  await pc.evaluate(() => {
    window.__maxGap = 0;
    let last = performance.now();
    window.__beat = setInterval(() => {
      const now = performance.now();
      window.__maxGap = Math.max(window.__maxGap, now - last);
      last = now;
    }, 16);
  });
  // Sanity check: a deliberate 150 ms block must be detected, or the measurement is meaningless.
  await pc.evaluate(() => {
    const end = performance.now() + 150;
    while (performance.now() < end);
  });
  await pc.waitForFunction(() => window.__maxGap >= 140, null, { timeout: 5000 });
  await pc.evaluate(() => (window.__maxGap = 0));
  const t0 = Date.now();
  await addFiles(pc, many);
  await pc.waitForFunction(() => document.querySelector("main")?.innerText.includes("400 documents"), null, { timeout: 120000 });
  await idle(pc, 180000);
  const importMs = Date.now() - t0;
  const worst = await pc.evaluate(() => (clearInterval(window.__beat), window.__maxGap));
  const rendered = await pc.locator('[data-testid="doc-row"]').count();
  assert(rendered < 80, `list not virtualized: ${rendered} rows in the DOM`);
  await pc.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight));
  await pc.waitForTimeout(300);
  await pc.locator('[data-testid="doc-row"]', { hasText: "Note 0" }).first().waitFor({ timeout: 5000 });
  const box = pc.getByRole("searchbox", { name: "Search documents" });
  const t1 = Date.now();
  await box.fill("ZX377Q");
  await pc.locator('[data-testid="search-result"]', { hasText: "Note 377" }).waitFor({ timeout: 10000 });
  const searchMs = Date.now() - t1;
  // Leaving the library and coming back restores the scroll position.
  await box.fill("");
  await pc.locator('[data-testid="doc-row"]').first().waitFor();
  await pc.evaluate(() => window.scrollTo(0, 9000));
  await pc.waitForTimeout(250);
  const before = await pc.evaluate(() => window.scrollY);
  // Click a row that is already in the viewport (Playwright would otherwise scroll first).
  await pc.evaluate(() => document.elementFromPoint(640, 450).closest('[data-testid="doc-row"]').querySelector("a").click());
  await pc.getByTestId("doc-title").waitFor();
  await pc.getByRole("link", { name: /^Library$/ }).last().click();
  await pc.locator('[data-testid="doc-row"]').first().waitFor();
  await pc.waitForTimeout(300);
  const after = await pc.evaluate(() => window.scrollY);
  assert(before > 5000 && Math.abs(after - before) < 150, `scroll not restored: ${before} → ${after}`);
  console.log(`      (import ${importMs}ms; longest main-thread stall ${Math.round(worst)}ms; DOM rows ${rendered}; search ${searchMs}ms incl. 110ms debounce)`);
  assert(worst < 500, `main thread blocked for ${Math.round(worst)}ms`);
  assert(searchMs < 2000, `search took ${searchMs}ms`);
});

// ── Context D: password-protected PDF (password used once, never stored) ─
const ctxD = await browser.newContext({ viewport: { width: 1360, height: 900 } });
watch(ctxD, "D");
const pd = await ctxD.newPage();
const encrypted = join(TMP, "bank-statement.pdf");
writeFileSync(encrypted, readFileSync(join(process.cwd(), "src/test/fixtures/encrypted-aes-128.pdf")));

await check("password-protected PDF: viewer and text extraction work with the password, which is never stored", async () => {
  await pd.goto(BASE);
  await addFiles(pd, [encrypted]);
  const row = pd.locator('[data-testid="doc-row"]', { hasText: "Bank statement" });
  await row.waitFor({ timeout: 20000 });
  await idle(pd);
  await row.getByText("Couldn't read").waitFor();
  await row.locator("a").click();
  await pd.getByText("This PDF is password-protected", { exact: true }).waitFor();
  await pd.getByTestId("viewer-password").fill("nope");
  await pd.getByRole("button", { name: "Open", exact: true }).click();
  await pd.getByText("That password didn’t work").waitFor({ timeout: 10000 });
  await pd.getByTestId("viewer-password").fill("user pw");
  await pd.getByRole("button", { name: "Open", exact: true }).click();
  await pd.locator('.pdf-page[data-rendered="true"]').first().waitFor({ timeout: 15000 });
  await pd.getByTestId("pdf-password").fill("user pw");
  await pd.getByRole("button", { name: "Read text" }).click();
  await pd.getByRole("tab", { name: /Extracted text/ }).click();
  await pd.locator('[data-testid="extracted-text"]', { hasText: "Hello secret world" }).waitFor({ timeout: 20000 });
  // Once unlocked, the PDF's own metadata title replaces the file-name title (the user hadn't edited it).
  await pd.getByTestId("doc-title").filter({ hasText: "Quarterly Report" }).waitFor({ timeout: 10000 });
  await search(pd, "secret world");
  await pd.locator('[data-testid="search-result"]', { hasText: "Quarterly Report" }).waitFor({ timeout: 10000 });
  const stored = await pd.evaluate(
    () =>
      new Promise((resolve) => {
        const req = indexedDB.open("papertrail");
        req.onsuccess = () => {
          const db = req.result;
          const tx = db.transaction(["documents", "settings"], "readonly");
          const a = tx.objectStore("documents").getAll();
          const b = tx.objectStore("settings").getAll();
          tx.oncomplete = () => {
            db.close();
            resolve(JSON.stringify([a.result, b.result, { ...localStorage }, { ...sessionStorage }]));
          };
        };
      }),
  );
  assert(!stored.includes("user pw"), "the PDF password was written to storage");
});

await check("no console errors and no requests to other origins", async () => {
  assert(!external.length, `external requests:\n${external.join("\n")}`);
  assert(!problems.length, `console errors:\n${problems.join("\n")}`);
});

await browser.close();
if (browser !== fixtureBrowser) await fixtureBrowser.close();
server.close();
rmSync(TMP, { recursive: true, force: true });
const failed = results.filter((r) => !r.ok);
console.log(`\n${results.length - failed.length}/${results.length} checks passed`);
if (failed.length) {
  for (const f of failed) console.log(`FAILED: ${f.name}\n  ${f.error}`);
  process.exit(1);
}
